    """Best effort for open bookings: distance / 20 km/h fallback, no Google Maps calls."""
    from geopy.distance import geodesic
    Booking = apps.get_model("api", "Booking")
    for b in Booking.objects.filter(status__in=[0, 1, 2, 5], window_start__isnull=True).iterator():
        try:
            km = geodesic((float(b.pickup_lat), float(b.pickup_long)),
                          (float(b.dropoff_lat), float(b.dropoff_long))).kilometers
        except (TypeError, ValueError):
            km = 0.0
        dur = max(int(math.ceil(km / 20.0 * 60)), 1)
        if b.is_advance and b.scheduled_pickup_at:
            start, end = b.scheduled_pickup_at, b.scheduled_pickup_at + timedelta(minutes=dur)
        elif b.created_at:
            start, end = b.created_at, b.created_at + timedelta(minutes=dur + 15)
        else:
            continue
        Booking.objects.filter(id=b.id).update(window_start=start, window_end=end, est_duration_minutes=dur)


